<script setup lang="ts">
import { computed, watch } from 'vue'
import { SDateTimeInput, SField, SForm, SFormModal, SInput, type Rules } from '@sub2api/ui'
import { paymentApi, usePaymentHost, type PromoCode } from '../host'
import { useModalForm } from './actions'

// Creates a promo code (an empty code is generated by the plugin) or edits
// one; the code itself is fixed once created (users may hold it already).
const props = defineProps<{ open: boolean; promo: PromoCode | null }>()
const emit = defineEmits<{ 'update:open': [open: boolean]; saved: [] }>()
const host = usePaymentHost()
const t = host.t

interface Draft extends Record<string, unknown> {
  code?: string
  bonus_amount?: number
  min_amount?: number
  max_uses?: number
  expires_at?: string
  notes?: string
}

const rules: Rules<Draft> = {
  code: { pattern: /^[A-Za-z0-9_-]{3,32}$/, message: () => t('admin.promo.form.codeInvalid') },
  bonus_amount: [{ required: true, type: 'number' }, { validator: (v) => Number(v) > 0 || t('admin.positive') }],
  min_amount: { required: true, type: 'number', min: 0 },
  max_uses: { required: true, type: 'integer', min: 0 },
  notes: { max: 200 }
}

const fromPromo = (p: PromoCode | null): Draft =>
  p ? { code: p.code, bonus_amount: p.bonus_amount, min_amount: p.min_amount, max_uses: p.max_uses, expires_at: p.expires_at, notes: p.notes }
    : { bonus_amount: 5, min_amount: 20, max_uses: 0 }
const { form, saving, reset, submit } = useModalForm<Draft>(() => fromPromo(props.promo), rules)
const editing = computed(() => !!props.promo)

watch(
  () => props.open,
  (open) => open && reset()
)

/** The request body: trimmed text, no code when editing or left empty. */
function body(d: Draft): Partial<PromoCode> {
  const code = editing.value ? undefined : d.code?.trim().toUpperCase() || undefined
  // An emptied expiry is sent as '' so an edit can take it away.
  const amounts = { bonus_amount: Number(d.bonus_amount), min_amount: Number(d.min_amount), max_uses: Number(d.max_uses) }
  return { code, ...amounts, expires_at: d.expires_at ?? '', notes: d.notes?.trim() ?? '' }
}

async function save() {
  const p = props.promo
  const ok = await submit((d) => (p ? paymentApi.updatePromoCode(p.id, body(d)) : paymentApi.createPromoCode(body(d))))
  if (!ok) return
  host.toast(t('admin.promo.saved'), 'success')
  emit('update:open', false)
  emit('saved')
}
</script>

<template>
  <SFormModal
    :open="open"
    :title="editing ? t('admin.promo.form.editTitle', { code: promo?.code }) : t('admin.promo.form.createTitle')"
    :loading="saving"
    @update:open="emit('update:open', $event)"
    @submit="save"
  >
    <SForm :form="form">
      <SField prop="code" :label="t('admin.promo.form.code')" :hint="editing ? t('admin.promo.form.codeFixed') : t('admin.promo.form.codeHint')">
        <SInput mono :disabled="editing" :placeholder="t('admin.promo.form.codePlaceholder')" v-bind="form.bind('code')" />
      </SField>
      <SField prop="bonus_amount" :label="t('admin.promo.form.bonus')" :hint="t('admin.promo.form.bonusHint')">
        <SInput type="number" min="0" step="0.01" suffix="USD" v-bind="form.bindNumber('bonus_amount')" />
      </SField>
      <SField prop="min_amount" :label="t('admin.promo.form.minAmount')" :hint="t('admin.promo.form.minAmountHint')">
        <SInput type="number" min="0" step="1" suffix="USD" v-bind="form.bindNumber('min_amount')" />
      </SField>
      <SField prop="max_uses" :label="t('admin.promo.form.maxUses')" :hint="t('admin.promo.form.maxUsesHint')">
        <SInput type="number" min="0" step="1" v-bind="form.bindNumber('max_uses')" />
      </SField>
      <SField prop="expires_at" :label="t('admin.promo.form.expires')" :hint="t('admin.promo.form.expiresHint')">
        <SDateTimeInput v-bind="form.bind('expires_at')" />
      </SField>
      <SField prop="notes" :label="t('admin.promo.form.notes')">
        <SInput v-bind="form.bind('notes')" />
      </SField>
    </SForm>
  </SFormModal>
</template>
